        RectF imageRect(){float scale=Math.min((getWidth()-dp(24))/(float)session.original.getWidth(),(getHeight()-dp(16))/(float)session.original.getHeight())*zoom;float w=session.original.getWidth()*scale,h=session.original.getHeight()*scale;return new RectF((getWidth()-w)/2+panX,(getHeight()-h)/2+panY,(getWidth()+w)/2+panX,(getHeight()+h)/2+panY);}
