        @Override protected void onDraw(Canvas canvas){if(session.original==null)return;RectF r=imageRect();paint.setColorFilter(null);canvas.drawBitmap(session.original,null,r,paint);paint.setColorFilter(new PorterDuffColorFilter(0x99F14E67,PorterDuff.Mode.SRC_IN));canvas.drawBitmap(session.mask,null,r,paint);paint.setColorFilter(null);}
