            if(event.getPointerCount()>1){cancelActive();float x=(event.getX(0)+event.getX(1))/2,y=(event.getY(0)+event.getY(1))/2;if(gesture&&event.getActionMasked()==MotionEvent.ACTION_MOVE){panX+=x-lastX;panY+=y-lastY;constrain();}lastX=x;lastY=y;gesture=true;getParent().requestDisallowInterceptTouchEvent(true);invalidate();return true;}
            if(gesture){if(event.getActionMasked()==MotionEvent.ACTION_UP||event.getActionMasked()==MotionEvent.ACTION_CANCEL){gesture=false;getParent().requestDisallowInterceptTouchEvent(false);}return true;}
            RectF r=imageRect();float x=Math.max(0,Math.min(session.original.getWidth()-1,(event.getX()-r.left)/r.width()*session.original.getWidth())),y=Math.max(0,Math.min(session.original.getHeight()-1,(event.getY()-r.top)/r.height()*session.original.getHeight()));
            if(event.getActionMasked()==MotionEvent.ACTION_DOWN){if(!r.contains(event.getX(),event.getY()))return false;getParent().requestDisallowInterceptTouchEvent(true);active=session.beginStroke(x,y);if(active!=null){session.totalPoints-=active.points.size()/2;session.strokes.remove(active);active=new Stroke(Math.max(1,session.brushSize/zoom),session.eraser);active.points.add(x);active.points.add(y);session.strokes.add(active);session.totalPoints++;session.rebuildMask();}invalidate();return true;}
