        private void deleteTemporaryOutput(File file){if(file==null)return;try{File canonical=file.getCanonicalFile();if(canonical.getParentFile().equals(documents().getCanonicalFile())&&canonical.getName().matches("erased-marks-[0-9a-fA-F-]{36}\\.png")&&!getApplication().getSharedPreferences("erase_shared_outputs",0).getBoolean(canonical.getName(),false))canonical.delete();}catch(IOException ignored){}}
        void deleteCapture(String path){try{File file=new File(path);if(file.getCanonicalFile().getParentFile().equals(captures().getCanonicalFile()))file.delete();}catch(Exception ignored){}}
        void load(Uri uri,boolean owned){if(busy)return;clearPdfSource();busy=true;status="Preparing image…";publish();worker.execute(()->{File copy=new File(captures(),"erase-input-"+UUID.randomUUID()+".img");try(InputStream in=getApplication().getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(copy)){if(in==null)throw new IOException();copy(in,out);}catch(Exception e){copy.delete();fail("Could not import image");return;}if(owned&&"file".equals(uri.getScheme()))deleteCapture(uri.getPath());prepare(copy,false);});}
